questions.solution:
async function processInSlices(items, perSlice, fn) {
  let slices = 0;
  for (let i = 0; i < items.length; i += perSlice) {
    for (const item of items.slice(i, i + perSlice)) fn(item);
    slices += 1;
    if (i + perSlice < items.length) await new Promise((resolve) => setTimeout(resolve, 0));
  }
  return slices;
}

let checks = 0;
const health = setInterval(() => checks++, 0);
const done = [];
const slices = await processInSlices([1, 2, 3, 4, 5, 6, 7], 3, (id) => done.push(id));
clearInterval(health);
console.log("processed:", done.length, "slices:", slices, "checks ran:", checks > 0);

