questions.solution:
function monitorLag(ms) {
  let expected = Date.now() + ms;
  let worst = 0;
  const timer = setInterval(() => {
    worst = Math.max(worst, Date.now() - expected);
    expected = Date.now() + ms;
  }, ms);
  return {
    stop() {
      clearInterval(timer);
      return worst;
    },
  };
}

const monitor = monitorLag(10);
await new Promise((resolve) => setTimeout(resolve, 15));
const end = Date.now() + 200;
while (Date.now() < end) {}
await new Promise((resolve) => setTimeout(resolve, 30));
console.log("saw the 200 ms block:", monitor.stop() > 100);

